<?php
namespace App\Models;
class Customer extends TenantModel { protected $casts=['start_date'=>'date','deactivated_at'=>'date','opening_balance'=>'decimal:2','is_active'=>'boolean']; protected $hidden=['passport_number']; protected static function booted():void{static::creating(fn($c)=>$c->qr_token=$c->qr_token??\Illuminate\Support\Str::uuid()->toString());} public function building(){return $this->belongsTo(Building::class);} public function room(){return $this->belongsTo(Room::class);} public function plans(){return $this->hasMany(CustomerPlan::class);} public function invoices(){return $this->hasMany(Invoice::class);} public function deliveries(){return $this->hasMany(Delivery::class);} public function payments(){return $this->hasMany(Payment::class);} public function pauses(){return $this->hasMany(MealPause::class);} public function skips(){return $this->hasMany(MealSkip::class);} public function ledger(){return $this->hasMany(LedgerEntry::class);} public function getMaskedPassportAttribute():string{return strlen($this->passport_number)>4 ? str_repeat('*',strlen($this->passport_number)-4).substr($this->passport_number,-4) : '****';} }
